case_001:
from app import clamp_percentage


def test_upper_boundary_still_valid():
    assert clamp_percentage(100) == 100


def test_out_of_range_values_still_rejected():
    for value in (-1, 101):
        try:
            clamp_percentage(value)
        except ValueError:
            pass
        else:
            raise AssertionError(f'{value} should be rejected')

